import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {hash,json} from './bounded-source-hash-20261026.mjs';import {clonePinnedWebsite} from './clone-pinned-website-stage-20261026.mjs';
const stage='F:/VisibleMedicine/staging/20261027-head-history-roles-website',pf='F:/VisibleMedicine/staging/20261027-head-history-regression-website/SOURCE_CANDIDATE.json',ph='1198d399a794d58480a97dbcc1bf695bf35628928fd98429131c593448216f1f',pr='F:/VisibleMedicine/staging/20261027-head-history-role-proposal';
const proposalFile=pr+'/PROPOSAL.json';assert.equal(hash(proposalFile),'eab97de47db777c1418f5c1eb0a7059e94e3f9c553a20abe818d96934840bb48');const proposal=json(proposalFile);
const {parent,site}=clonePinnedWebsite({stage,parentFile:pf,parentSha256:ph});
for(const f of proposal.files){const file=site+'/'+f.path;assert.equal(hash(file),f.preimageSha256);assert.equal(hash(pr+'/'+f.path),f.proposedSha256);const before=fs.readFileSync(file),after=fs.readFileSync(pr+'/'+f.path);let forward=Buffer.from(before),inverse=Buffer.from(after);for(const op of [...f.operations].reverse()){assert.equal(forward.subarray(op.beforeStart,op.beforeEnd).toString(),op.from);forward=Buffer.concat([forward.subarray(0,op.beforeStart),Buffer.from(op.to),forward.subarray(op.beforeEnd)]);assert.equal(inverse.subarray(op.afterStart,op.afterEnd).toString(),op.to);inverse=Buffer.concat([inverse.subarray(0,op.afterStart),Buffer.from(op.from),inverse.subarray(op.afterEnd)]);}assert.deepEqual(forward,after);assert.deepEqual(inverse,before);fs.copyFileSync(pr+'/'+f.path,file);}
for(const p of ['next-env.d.ts','.next/types/routes.d.ts']){const from=parent.website+'/'+p,to=site+'/'+p;if(!fs.existsSync(to)){fs.mkdirSync(path.dirname(to),{recursive:true});fs.copyFileSync(from,to,fs.constants.COPYFILE_EXCL);}assert.equal(hash(from),hash(to));}
const rows=parent.sourceRows.map(r=>{const digest=hash(site+'/'+r.path);assert.equal(digest,proposal.files.find(f=>f.path===r.path)?.proposedSha256??r.sha256,r.path);return {...r,sha256:digest,bytes:fs.statSync(site+'/'+r.path).size}});
for(const r of json(site+'/atlas-review/integration-inputs.json').inputs)assert.equal(hash(site+'/'+r.path),r.sha256,r.path);
const source={...parent,schema:'vm-head-history-roles-successor/1',at:new Date().toISOString(),website:site,parent:pf,parentSha256:ph,sourceRows:rows,changedPaths:proposal.files.map(f=>f.path),roleProposal:{path:proposalFile,sha256:hash(proposalFile)},allApplicationReviewRuntimeAndLicenceBytesUnchanged:true,allOriginalAssertionsRetained:true,independentCurrentSourceAndTamperChecksAdded:true,unresolvedHistoricalRoot:null};
fs.writeFileSync(stage+'/SOURCE_CANDIDATE.json',JSON.stringify(source,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({source:stage+'/SOURCE_CANDIDATE.json',sha256:hash(stage+'/SOURCE_CANDIDATE.json'),paths:rows.length}));
